changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.catalog_owner_is_curator(p_tenant text, p_segment text) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER AS $fn$ SELECT EXISTS ( SELECT 1 FROM nexus.catalog_owners w WHERE w.tenant_id = p_tenant AND w.tumbler_prefix = replace(p_segment, '-', '.') AND w.owner_type = 'curator' ) $fn$;
CREATE OR REPLACE FUNCTION nexus.catalog_collection_owner_replaceable(p_tenant text, p_owner text) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER AS $fn$ SELECT COALESCE(p_owner !~ '^[0-9]+(-[0-9]+)*$', true) OR nexus.catalog_owner_is_curator(p_tenant, p_owner) $fn$;
CREATE OR REPLACE FUNCTION nexus.catalog_collection_doc_owner(p_tenant text, p_collection text) RETURNS text LANGUAGE sql STABLE SECURITY INVOKER AS $fn$ SELECT o.seg FROM ( SELECT split_part(d.tumbler, '.', 1) || '-' || split_part(d.tumbler, '.', 2) AS seg, count(*) AS n FROM nexus.catalog_documents d WHERE d.tenant_id = p_tenant AND d.physical_collection = p_collection AND d.deleted_at IS NULL AND d.tumbler ~ '^[0-9]+\.[0-9]+\.[0-9]+' GROUP BY 1 ) o ORDER BY (NOT nexus.catalog_owner_is_curator(p_tenant, o.seg)) DESC, o.n DESC, o.seg LIMIT 1 $fn$;

rollback.sql:
DROP FUNCTION IF EXISTS nexus.catalog_collection_doc_owner(text, text);
DROP FUNCTION IF EXISTS nexus.catalog_collection_owner_replaceable(text, text);
DROP FUNCTION IF EXISTS nexus.catalog_owner_is_curator(text, text);

changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.catalog_collections_owner_from_docs()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $fn$
DECLARE
    v_owner text;
BEGIN
    IF NEW.content_type IN ('code', 'docs', 'rdr')
       AND nexus.catalog_collection_owner_replaceable(NEW.tenant_id, NEW.owner_id) THEN
        v_owner := nexus.catalog_collection_doc_owner(NEW.tenant_id, NEW.name);
        IF v_owner IS NOT NULL AND v_owner IS DISTINCT FROM NEW.owner_id THEN
            RAISE NOTICE 'catalog-044: collection % owner_id % -> % (from its documents)',
                NEW.name, NEW.owner_id, v_owner;
            NEW.owner_id := v_owner;
        END IF;
    END IF;
    RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS catalog_collections_owner_from_docs ON nexus.catalog_collections;
CREATE TRIGGER catalog_collections_owner_from_docs
    BEFORE INSERT OR UPDATE OF owner_id, content_type ON nexus.catalog_collections
    FOR EACH ROW EXECUTE FUNCTION nexus.catalog_collections_owner_from_docs();

CREATE OR REPLACE FUNCTION nexus.catalog_documents_owner_to_collection()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $fn$
DECLARE
    v_seg text;
    v_cur text;
    v_new text;
BEGIN
    IF NEW.deleted_at IS NULL
       AND NEW.physical_collection <> ''
       AND NEW.tumbler ~ '^[0-9]+\.[0-9]+\.[0-9]+' THEN
        v_seg := split_part(NEW.tumbler, '.', 1) || '-' || split_part(NEW.tumbler, '.', 2);
        SELECT c.owner_id INTO v_cur
          FROM nexus.catalog_collections c
         WHERE c.tenant_id = NEW.tenant_id
           AND c.name = NEW.physical_collection
           AND c.content_type IN ('code', 'docs', 'rdr');
        -- Cheap probes first: a settled repo collection (a tumbler-shaped, non-curator
        -- owner) or one already owned by this very document's owner costs a primary-key
        -- read and an owner-row read, never the aggregate over the collection's documents.
        IF FOUND
           AND v_cur IS DISTINCT FROM v_seg
           AND nexus.catalog_collection_owner_replaceable(NEW.tenant_id, v_cur) THEN
            v_new := nexus.catalog_collection_doc_owner(NEW.tenant_id, NEW.physical_collection);
            IF v_new IS NOT NULL AND v_new IS DISTINCT FROM v_cur THEN
                RAISE NOTICE 'catalog-044: collection % owner_id % -> % (from its documents)',
                    NEW.physical_collection, v_cur, v_new;
                UPDATE nexus.catalog_collections c
                   SET owner_id = v_new
                 WHERE c.tenant_id = NEW.tenant_id
                   AND c.name = NEW.physical_collection
                   AND c.content_type IN ('code', 'docs', 'rdr')
                   AND c.owner_id IS DISTINCT FROM v_new
                   -- Re-checked on the row being updated: under READ COMMITTED a concurrent
                   -- transaction may have committed a repo owner since the SELECT above, and
                   -- this predicate is re-evaluated against that new row version, so a curator
                   -- (or slug) derivation cannot overwrite it.
                   AND nexus.catalog_collection_owner_replaceable(c.tenant_id, c.owner_id);
            END IF;
        END IF;
    END IF;
    RETURN NULL;
END;
$fn$;

DROP TRIGGER IF EXISTS catalog_documents_owner_to_collection ON nexus.catalog_documents;
CREATE TRIGGER catalog_documents_owner_to_collection
    AFTER INSERT OR UPDATE OF physical_collection, deleted_at ON nexus.catalog_documents
    FOR EACH ROW EXECUTE FUNCTION nexus.catalog_documents_owner_to_collection();

rollback.sql:
DROP TRIGGER IF EXISTS catalog_documents_owner_to_collection ON nexus.catalog_documents;
DROP TRIGGER IF EXISTS catalog_collections_owner_from_docs ON nexus.catalog_collections;
DROP FUNCTION IF EXISTS nexus.catalog_documents_owner_to_collection();
DROP FUNCTION IF EXISTS nexus.catalog_collections_owner_from_docs();

changeSet.sql:
ALTER TABLE nexus.catalog_documents NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_owners NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_collections NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_repaired BIGINT;
BEGIN
    UPDATE nexus.catalog_collections c
       SET owner_id = d.seg
      FROM (
          SELECT c2.tenant_id, c2.name,
                 nexus.catalog_collection_doc_owner(c2.tenant_id, c2.name) AS seg
            FROM nexus.catalog_collections c2
           WHERE c2.content_type IN ('code', 'docs', 'rdr')
             AND nexus.catalog_collection_owner_replaceable(c2.tenant_id, c2.owner_id)
      ) d
     WHERE c.tenant_id = d.tenant_id
       AND c.name = d.name
       AND d.seg IS NOT NULL
       AND c.owner_id IS DISTINCT FROM d.seg;
    GET DIAGNOSTICS v_repaired = ROW_COUNT;
    RAISE NOTICE 'catalog-044-3: re-derived owner_id from documents for % collection row(s)', v_repaired;
END $$;

ALTER TABLE nexus.catalog_collections FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_owners FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_documents FORCE ROW LEVEL SECURITY;
